// ProgressBar — Gtk.ProgressBar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles progressbar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface ProgressBarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Pango.EllipsizeMode, from Gtk.ProgressBar */
  ellipsize?: ReactNode

  /** gdouble, from Gtk.ProgressBar */
  fraction?: number

  /** gboolean, from Gtk.ProgressBar */
  inverted?: boolean

  /** gdouble, from Gtk.ProgressBar */
  pulseStep?: number

  /** gboolean, from Gtk.ProgressBar */
  showText?: boolean

  /** utf8, from Gtk.ProgressBar */
  text?: string
}

export function ProgressBar({ className, children, text }: ProgressBarProps) {
  return (
    <div className={cn(className)}>
      {text}
      {children}
    </div>
  )
}
